SELECT codecd as code, codenm, remark as etcval
FROM haba900t_tbl
WHERE useyn = 'Y'

    AND cdtype = #{gbncd}


    AND codecd = #{code}

ORDER BY dspord

SELECT custcd, custnm, ceo, telno, address FROM haba020t_tbl WHERE cmpycd = #{cmpycd}
AND custnm LIKE CONCAT('%', #{custnm}, '%')
ORDER BY custnm
